require_once __DIR__ . '/../../app/bootstrap.php'; require_once __DIR__ . '/../../app/operational_writes.php';$action=(string)($_POST['accion']??'');$permission=['registrar'=>'INCIDENCIAS_REGISTRAR','resolver'=>'INCIDENCIAS_RESOLVER'][$action]??null;if($permission===null){operation_error('Acción no disponible.',404);}require_operation_post($permission);try{if($action==='registrar'){$request=operation_id($_POST['solicitud_id']??null);$type=operation_id($_POST['tipo_incidencia_id']??null);$description=operation_text($_POST['descripcion']??null,500);$sql='DECLARE @incidencia_id INT; EXEC dbo.sp_registrar_incidencia @solicitud_id=?,@tipo_incidencia_id=?,@descripcion=?,@incidencia_id=@incidencia_id OUTPUT;';$params=[$request,$type,$description];$message='Incidencia registrada correctamente.';}else{$incident=operation_id($_POST['incidencia_id']??null);$resolution=operation_text($_POST['resolucion']??null,500);$sql='EXEC dbo.sp_resolver_incidencia @incidencia_id=?,@resolucion=?;';$params=[$incident,$resolution];$message='Incidencia resuelta correctamente.';}}catch(InvalidArgumentException $exception){operation_error($exception->getMessage());}try{$stmt=db()->prepare($sql);$stmt->execute($params);$stmt->closeCursor();}catch(PDOException $exception){operation_sql_error($exception,[50402=>'La descripción es obligatoria.',50404=>'Indica la resolución.',50405=>'La incidencia no existe o ya fue resuelta.']);}operation_success($message,'incidenciaActualizada','/entregas.php?seccion=incidencias');
